<?php
namespace App\Http\Controllers;
use App\Models\{ApprovalHistory,Leave};use App\Services\RequestNotifier;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class LeaveController extends Controller {
 public function mine(Request $r){$leaves=$r->user()->leaves()->latest()->paginate(20);return view('leaves.mine',compact('leaves'));}
 public function index(Request $r){$this->authorize('viewAny',Leave::class);$u=$r->user();$q=Leave::with(['user','histories.actor']);if(!$u->hasPermission('requests.finalize'))$q->whereHas('user',fn($x)=>$x->where('manager_id',$u->id)->orWhereIn('department_id',$u->hodDepartments()->pluck('departments.id')));$leaves=$q->latest()->paginate(20);return view('leaves.index',compact('leaves'));}
 public function store(Request $r,RequestNotifier $notifier){$data=$r->validate(['leave_type'=>'required|in:medical,casual,half_day,emergency','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','reason'=>'nullable|string|max:2000','medical_certificate'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:5120']);if($r->hasFile('medical_certificate'))$data['medical_certificate_path']=$r->file('medical_certificate')->store('medical-certificates','public');$leave=$r->user()->leaves()->create($data+['status'=>'pending_manager']);$notifier->created($leave->load('user'),'leave');return back()->with('success','Leave request submitted for manager approval.');}
 public function decision(Request $r,Leave $leave,string $decision,RequestNotifier $notifier){$this->authorize('decide',$leave);abort_unless(in_array($decision,['approve','reject']),404);$data=$r->validate(['note'=>'nullable|string|max:1000']);$previous=$leave->status;$admin=$r->user()->hasPermission('requests.finalize');if($admin){abort_unless(in_array($leave->status,['pending_admin','pending_manager','pending']),422,'Request is not awaiting final approval.');$status=$decision==='approve'?'approved':'rejected';$leave->update(['approved_by_admin'=>$decision==='approve','admin_approved_by'=>$r->user()->id,'approved_by'=>$r->user()->id,'status'=>$status,'resolved_at'=>now(),'decision_note'=>$data['note']??null]);$stage='admin';}else{abort_unless(in_array($leave->status,['pending_manager','pending']),422,'Request is not awaiting manager approval.');$status=$decision==='approve'?'pending_admin':'rejected';$leave->update(['approved_by_manager'=>$decision==='approve','manager_approved_by'=>$r->user()->id,'approved_by'=>$r->user()->id,'status'=>$status,'resolved_at'=>$decision==='reject'?now():null,'decision_note'=>$data['note']??null]);$stage='manager';}ApprovalHistory::create(['approvable_type'=>Leave::class,'approvable_id'=>$leave->id,'acted_by'=>$r->user()->id,'stage'=>$stage,'action'=>$decision,'previous_status'=>$previous,'new_status'=>$status,'note'=>$data['note']??null]);$notifier->decided($leave->load('user'),'leave',$status);return back()->with('success','Leave request '.str_replace('_',' ',$status).'.');}
 public function certificate(Request $r,Leave $leave){$this->authorize('viewAny',Leave::class);abort_unless($leave->medical_certificate_path&&Storage::disk('public')->exists($leave->medical_certificate_path),404);return Storage::disk('public')->response($leave->medical_certificate_path);}
}
